    "{0} GAME(S) IN THE LIBRARY · CHECKED FOR NEW ONES EACH TIME THE APP OPENS" to Tr(ja = "ライブラリに ゲーム {0}こ · アプリを ひらく たびに あたらしい ゲームを さがします", fr = "{0} JEU(X) DANS LA BIBLIOTHÈQUE · NOUVEAUX JEUX CHERCHÉS À CHAQUE OUVERTURE", de = "{0} SPIEL(E) IN DER BIBLIOTHEK · BEI JEDEM APP-START AUF NEUE GEPRÜFT", it = "{0} GIOCHI NELLA LIBRERIA · NUOVI CERCATI A OGNI AVVIO DELL'APP", es = "{0} JUEGO(S) EN LA BIBLIOTECA · SE BUSCAN NUEVOS CADA VEZ QUE SE ABRE LA APP"),
