    "NO CHEATS FOR THIS GAME" to Tr(ja = "この ゲームの チートは ありません", fr = "AUCUNE TRICHE POUR CE JEU", de = "KEINE CHEATS FÜR DIESES SPIEL", it = "NESSUN TRUCCO PER QUESTO GIOCO", es = "NINGÚN TRUCO PARA ESTE JUEGO"),
    "ADD THEM IN SETTINGS ON THE TOP SCREEN" to Tr(ja = "うえの がめんの せっていで ついか", fr = "À AJOUTER DANS LES OPTIONS DE L'ÉCRAN DU HAUT", de = "IN DEN OPTIONEN OBEN HINZUFÜGEN", it = "AGGIUNGILI NELLE OPZIONI DELLO SCHERMO IN ALTO", es = "AÑÁDELOS EN AJUSTES EN LA PANTALLA DE ARRIBA"),
    "NO GAMES IN THE LIBRARY" to Tr(ja = "ライブラリに ゲームが ありません", fr = "AUCUN JEU DANS LA BIBLIOTHÈQUE", de = "KEINE SPIELE IN DER BIBLIOTHEK", it = "NESSUN GIOCO IN LIBRERIA", es = "NINGÚN JUEGO EN LA BIBLIOTECA"),
    "A cheat can break a save, so the save is backed up every time a game starts (RESTORE BACKUP in its library menu). Achievements pause while a cheat is on." to Tr(ja = "チートで セーブが こわれる ことも あるので ゲームを はじめる たびに セーブの バックアップを とります (ライブラリの メニューの バックアップを もどす)。 チートが オンの あいだ じっせきは とまります。", fr = "Une triche peut abîmer une sauvegarde : elle est copiée à chaque lancement (RESTAURER COPIE dans le menu du jeu). Les succès sont en pause tant qu'une triche est active.", de = "Ein Cheat kann einen Spielstand beschädigen: Er wird bei jedem Start gesichert (BACKUP LADEN im Menü des Spiels). Erfolge pausieren, solange ein Cheat an ist.", it = "Un trucco può rovinare un salvataggio: viene copiato a ogni avvio (RIPRISTINA BACKUP nel menu del gioco). Gli obiettivi sono in pausa finché un trucco è attivo.", es = "Un truco puede estropear una partida: se copia cada vez que empieza un juego (RESTAURAR COPIA en su menú). Los logros se pausan mientras haya un truco activo."),
    "Type or paste a GameShark, Action Replay or CodeBreaker code, one line or many. AUTO works out which it is; pick the type when a code doesn't take." to Tr(ja = "ゲームシャーク アクションリプレイ コードブレイカーの コードを いれてください (なんぎょうでも)。 オートで しゅるいを みわけます。 うまく いかない ときは しゅるいを えらんでください。", fr = "Tapez ou collez un code GameShark, Action Replay ou CodeBreaker, sur une ou plusieurs lignes. AUTO trouve lequel c'est ; choisissez le type si un code ne passe pas.", de = "Tippe oder füge einen GameShark-, Action-Replay- oder CodeBreaker-Code ein, eine Zeile oder mehrere. AUTO erkennt die Art; wähle den Typ, wenn ein Code nicht klappt.", it = "Scrivi o incolla un codice GameShark, Action Replay o CodeBreaker, su una o più righe. AUTO capisce quale è; scegli il tipo se un codice non funziona.", es = "Escribe o pega un código GameShark, Action Replay o CodeBreaker, en una línea o varias. AUTO averigua cuál es; elige el tipo si un código no funciona."),
    "e.g. INFINITE MONEY" to Tr(ja = "れい: おかね むげん", fr = "ex. ARGENT INFINI", de = "z. B. UNENDLICH GELD", it = "es. SOLDI INFINITI", es = "p. ej. DINERO INFINITO"),
    "That isn't a code." to Tr(ja = "コードでは ありません。", fr = "Ce n'est pas un code.", de = "Das ist kein Code.", it = "Questo non è un codice.", es = "Eso no es un código."),
    "mGBA can't read {0} as a {1} code." to Tr(ja = "{0}を {1}の コードとして よめません。", fr = "mGBA ne peut pas lire {0} comme un code {1}.", de = "mGBA kann {0} nicht als {1}-Code lesen.", it = "mGBA non riesce a leggere {0} come codice {1}.", es = "mGBA no puede leer {0} como código {1}."),
    "mGBA can't read {0}." to Tr(ja = "{0}が よめません。", fr = "mGBA ne peut pas lire {0}.", de = "mGBA kann {0} nicht lesen.", it = "mGBA non riesce a leggere {0}.", es = "mGBA no puede leer {0}."),
    "NO CHEATS ADDED" to Tr(ja = "チートは ついか されませんでした", fr = "AUCUNE TRICHE AJOUTÉE", de = "KEINE CHEATS HINZUGEFÜGT", it = "NESSUN TRUCCO AGGIUNTO", es = "NINGÚN TRUCO AÑADIDO"),
    "CAN'T READ THAT FILE" to Tr(ja = "ファイルが よめません", fr = "FICHIER ILLISIBLE", de = "DATEI NICHT LESBAR", it = "FILE NON LEGGIBILE", es = "NO SE PUEDE LEER"),
    "Pick a RetroArch .cht or an mGBA .cheats file." to Tr(ja = "RetroArchの .cht か mGBAの .cheats ファイルを えらんでください。", fr = "Choisissez un fichier .cht de RetroArch ou .cheats de mGBA.", de = "Wähle eine .cht-Datei von RetroArch oder eine .cheats-Datei von mGBA.", it = "Scegli un file .cht di RetroArch o .cheats di mGBA.", es = "Elige un archivo .cht de RetroArch o .cheats de mGBA."),
    "NO CHEATS FOUND" to Tr(ja = "チートが ありません", fr = "AUCUNE TRICHE TROUVÉE", de = "KEINE CHEATS GEFUNDEN", it = "NESSUN TRUCCO TROVATO", es = "NO HAY TRUCOS"),
    "That file has no cheats in a format PokeDaisy reads (RetroArch .cht, mGBA .cheats)." to Tr(ja = "この ファイルには よめる チートが ありません (RetroArchの .cht mGBAの .cheats)。", fr = "Ce fichier n'a aucune triche dans un format lu par PokeDaisy (.cht de RetroArch, .cheats de mGBA).", de = "Die Datei hat keine Cheats in einem Format, das PokeDaisy liest (RetroArch .cht, mGBA .cheats).", it = "Il file non ha trucchi in un formato che PokeDaisy legge (.cht di RetroArch, .cheats di mGBA).", es = "El archivo no tiene trucos en un formato que PokeDaisy lea (.cht de RetroArch, .cheats de mGBA)."),
    "{0} CHEATS ADDED" to Tr(ja = "チートを {0}こ ついか", fr = "{0} TRICHES AJOUTÉES", de = "{0} CHEATS HINZUGEFÜGT", it = "{0} TRUCCHI AGGIUNTI", es = "{0} TRUCOS AÑADIDOS"),
    "They start OFF: tap one to turn it on." to Tr(ja = "さいしょは オフです。 タッチで オンに なります。", fr = "Elles sont désactivées : touchez-en une pour l'activer.", de = "Sie sind aus: tippe einen an, um ihn einzuschalten.", it = "Partono spenti: tocca un trucco per attivarlo.", es = "Empiezan desactivados: toca uno para activarlo."),
    "{0} left out: mGBA can't read {1} of their code lines." to Tr(ja = "{0}こは はずしました: {1}ぎょうの コードが よめません。", fr = "{0} ignorées : mGBA ne peut pas lire {1} de leurs lignes de code.", de = "{0} ausgelassen: mGBA kann {1} ihrer Codezeilen nicht lesen.", it = "{0} esclusi: mGBA non riesce a leggere {1} delle loro righe di codice.", es = "{0} omitidos: mGBA no puede leer {1} de sus líneas de código."),
    "{0} were already in the list." to Tr(ja = "{0}こは もう リストに あります。", fr = "{0} étaient déjà dans la liste.", de = "{0} waren schon in der Liste.", it = "{0} erano già nell'elenco.", es = "{0} ya estaban en la lista."),
    "CHEATS ON" to Tr(ja = "チート オン", fr = "TRICHES ACTIVES", de = "CHEATS AN", it = "TRUCCHI ATTIVI", es = "TRUCOS ACTIVOS"),
    "CHEATS OFF" to Tr(ja = "チート オフ", fr = "TRICHES COUPÉES", de = "CHEATS AUS", it = "TRUCCHI SPENTI", es = "TRUCOS DESACTIVADOS"),
    "PAUSED: CHEATS ON" to Tr(ja = "ていし: チート オン", fr = "EN PAUSE : TRICHES", de = "PAUSE: CHEATS AN", it = "IN PAUSA: TRUCCHI", es = "EN PAUSA: TRUCOS"),
    "Achievements are paused until every cheat is off." to Tr(ja = "チートが すべて オフに なるまで じっせきは とまります。", fr = "Les succès sont en pause jusqu'à ce que toutes les triches soient coupées.", de = "Erfolge pausieren, bis alle Cheats aus sind.", it = "Gli obiettivi sono in pausa finché tutti i trucchi non sono spenti.", es = "Los logros se pausan hasta que todos los trucos estén desactivados."),
    "Achievements are back on." to Tr(ja = "じっせきが もどりました。", fr = "Les succès reprennent.", de = "Erfolge sind wieder an.", it = "Gli obiettivi sono di nuovo attivi.", es = "Los logros vuelven a estar activos."),
)
